//! 🧪️ The bounded writer matches the independently generated language-neutral history wire cases.
use super::*;
#[test]
fn original_transition_wire_preserves_every_portable_payload_without_heap_birth(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🧫️history-transition/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){if case["expect"]["outcome"]!="accepted"{continue}let hex=case["payloadHex"].as_str().unwrap();let bytes:Vec<u8>=(0..hex.len()).step_by(2).map(|at|u8::from_str_radix(&hex[at..at+2],16).unwrap()).collect();let source=decode_history_transition(&bytes).unwrap();for width in [1,7,4096]{let mut cursor=HistoryTransitionWireCursor::default();let mut output=Vec::new();let mut page=[0u8;4096];while !cursor.is_finished(){let(used,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.write(&source,&mut page[..width]).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));output.extend_from_slice(&page[..used]);assert!(used!=0||cursor.is_finished());}assert_eq!(output,bytes,"{}",case["id"]);assert_eq!(cursor.written(),bytes.len());assert_eq!(cursor.write(&source,&mut page).unwrap(),0);}}
}
#[test]
fn original_transition_wire_refuses_a_foreign_source_before_mutating_recipient(){let source=HistoryTransition::Branch{alternative_id:"a".into(),name:"b".into(),checkpoint_id:"c".into()};let foreign=source.clone();let mut cursor=HistoryTransitionWireCursor::default();let mut output=[37u8;1];assert_eq!(cursor.write(&source,&mut []).unwrap(),0);assert_eq!(cursor.write(&source,&mut output).unwrap(),1);output[0]=37;assert!(cursor.write(&foreign,&mut output).is_err());assert_eq!(output,[37]);}

fn drafts(case:&serde_json::Value)->HistoryInputDrafts{case["inputs"].as_array().unwrap().iter().map(|row|(MutationId(row["target"].as_str().unwrap().into()),if row["withdrawn"]==true{InputReplacement::Withdrawn}else{InputReplacement::Input{schema:row["schema"].as_str().unwrap().into(),payload:(0..row["payloadLength"].as_u64().unwrap()).map(|index|(row["payloadSeed"].as_u64().unwrap()+index*31)as u8).collect()}})).collect()}
#[test]
fn original_supersession_wire_borrows_ranked_drafts_and_matches_portable_sha256(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){let source=drafts(case);let scope=case["scope"].as_str();let pointers=source.iter().map(|(target,input)|(target.0.as_ptr(),match input{InputReplacement::Input{payload,..}=>Some(payload.as_ptr()),_=>None})).collect::<Vec<_>>();for width in law["bodyBytes"].as_array().unwrap(){let mut cursor=HistoryTransitionWireCursor::default();let mut output=Vec::new();let mut page=[0u8;4096];while !cursor.is_finished(){let(used,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.write_supersession(&source,scope,&mut page[..width.as_u64().unwrap()as usize]).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(used!=0||cursor.is_finished());output.extend_from_slice(&page[..used]);}assert_eq!(output.len(),case["wireBytes"].as_u64().unwrap()as usize);let mut hash=semio_framework_hash::Sha256::new();hash.update(&output);assert_eq!(hash.finalize().iter().map(|byte|format!("{byte:02x}")).collect::<String>(),case["sha256"].as_str().unwrap());let HistoryTransition::Supersede(decoded)=decode_history_transition(&output).unwrap()else{panic!("supersession payload tag")};assert_eq!(decoded.scope.as_deref(),scope);assert!(decoded.inputs.iter().zip(source.iter()).all(|(decoded,(target,input))|decoded.target==*target&&decoded.replacement==*input));assert_eq!(source.iter().map(|(target,input)|(target.0.as_ptr(),match input{InputReplacement::Input{payload,..}=>Some(payload.as_ptr()),_=>None})).collect::<Vec<_>>(),pointers);}}
}
#[test]
fn original_supersession_wire_refuses_foreign_scope_source_and_mutated_draft_epoch(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut source=drafts(&law["cases"][1]);let foreign=source.clone();let scope=String::from("alternative:original");let foreign_scope=scope.clone();let mut cursor=HistoryTransitionWireCursor::default();let mut page=[37u8;1];assert_eq!(cursor.write_supersession(&source,Some(&scope),&mut []).unwrap(),0);assert_eq!(cursor.write_supersession(&source,Some(&scope),&mut page).unwrap(),1);page[0]=37;for(drafts,scope)in [(&foreign,scope.as_str()),(&source,foreign_scope.as_str())]{assert!(cursor.write_supersession(drafts,Some(scope),&mut page).is_err());assert_eq!(page,[37]);}source.insert(MutationId("energy:001".into()),InputReplacement::Withdrawn);assert!(cursor.write_supersession(&source,Some(&scope),&mut page).is_err());assert_eq!(page,[37]);assert!(HistoryTransitionWireCursor::default().write_supersession(&HistoryInputDrafts::new(),None,&mut page).is_err());assert_eq!(page,[37]);
}

struct FixturePins<'a>(&'a[TransitionPin]);
impl HistoryTransitionPinSource for FixturePins<'_>{fn source_identity(&self)->(usize,usize){(self.0.as_ptr()as usize,self.0.len())}fn len(&self)->usize{self.0.len()}fn uri_part(&self,row:usize,part:usize)->Option<&str>{self.0.get(row).and_then(|pin|match part{0=>Some(pin.child_uri.as_str()),1..=6=>Some(""),_=>None})}fn checkpoint_id(&self,row:usize)->Option<&str>{self.0.get(row).map(|pin|pin.checkpoint_id.as_str())}}
fn borrowed_write(cursor:&mut HistoryTransitionWireCursor,source:&HistoryTransition,epoch:u64,output:&mut[u8])->Result<usize,ValueError>{match source{HistoryTransition::Repin{checkpoint_id,pinned_checkpoint_id,pins}=>cursor.write_repin_view(&HistoryTransitionRepinView{checkpoint_id,pinned_checkpoint_id,pins:&FixturePins(pins)},epoch,output),HistoryTransition::Revert{mutation_ids}=>cursor.write_edits_view(&HistoryTransitionEditsView{mode:HistoryTransitionEditMode::Revert,mutation_ids},epoch,output),HistoryTransition::Reinstate{mutation_ids}=>cursor.write_edits_view(&HistoryTransitionEditsView{mode:HistoryTransitionEditMode::Reinstate,mutation_ids},epoch,output),HistoryTransition::Commit(c)=>cursor.write_commit_view(&HistoryTransitionCommitView{checkpoint_id:&c.checkpoint_id,parent_id:c.parent_id.as_deref(),change_id:&c.change_id,mutation_ids:&c.mutation_ids,description:c.description.as_deref(),saved_at:&c.saved_at,authors:&c.authors,message:c.message.as_deref(),timestamp:&c.timestamp,line_id:c.line_id.as_deref()},epoch,output),HistoryTransition::Branch{alternative_id,name,checkpoint_id}=>cursor.write_branch_view(&HistoryTransitionBranchView{alternative_id,name,checkpoint_id},epoch,output),_=>panic!("borrowed history fixture must select Commit or Branch")}}
#[test]
fn original_borrowed_graph_and_edit_fields_match_portable_wire_without_temporary_owned_records(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🧫️history-transition/🔣️.json")).unwrap();let mut checked=0;
 for case in law["cases"].as_array().unwrap(){if case["expect"]["outcome"]!="accepted"{continue}let hex=case["payloadHex"].as_str().unwrap();let bytes:Vec<_>=(0..hex.len()).step_by(2).map(|at|u8::from_str_radix(&hex[at..at+2],16).unwrap()).collect();let source=decode_history_transition(&bytes).unwrap();if !matches!(source,HistoryTransition::Commit(_)|HistoryTransition::Branch{..}|HistoryTransition::Revert{..}|HistoryTransition::Reinstate{..}|HistoryTransition::Repin{..}){continue}checked+=1;for width in [1,7,4096]{let mut cursor=HistoryTransitionWireCursor::default();let mut output=Vec::new();let mut page=[0;4096];for index in 0..100000{if cursor.is_finished(){break}let(used,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||borrowed_write(&mut cursor,&source,71,&mut page[..width]).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));output.extend_from_slice(&page[..used]);assert!(index<99999);}assert_eq!(output,bytes,"{}",case["id"]);assert_eq!(cursor.written(),bytes.len());}}
 assert!(checked>=7);
}
#[test]
fn original_borrowed_history_refuses_foreign_field_backings_and_epoch_before_writing(){
 let alternative_id="alternative";let name=String::from("Name λ");let checkpoint_id="checkpoint";let foreign_name=name.clone();let view=HistoryTransitionBranchView{alternative_id,name:&name,checkpoint_id};let mut cursor=HistoryTransitionWireCursor::default();let mut output=[37;1];assert_eq!(cursor.write_branch_view(&view,71,&mut output).unwrap(),1);output[0]=37;assert!(cursor.write_branch_view(&view,72,&mut output).is_err());assert!(cursor.write_branch_view(&HistoryTransitionBranchView{name:&foreign_name,..view},71,&mut output).is_err());assert_eq!(output,[37]);
 let timestamp=String::from("time");let foreign_timestamp=timestamp.clone();let ids=vec![MutationId("operation".into())];let commit=HistoryTransitionCommitView{checkpoint_id,parent_id:None,change_id:"change",mutation_ids:&ids,description:None,saved_at:"saved",authors:&[],message:None,timestamp:&timestamp,line_id:None};let mut cursor=HistoryTransitionWireCursor::default();assert_eq!(cursor.write_commit_view(&commit,71,&mut output).unwrap(),1);output[0]=37;assert!(cursor.write_commit_view(&commit,72,&mut output).is_err());assert!(cursor.write_commit_view(&HistoryTransitionCommitView{timestamp:&foreign_timestamp,..commit},71,&mut output).is_err());assert_eq!(output,[37]);
}

#[test]
fn original_borrowed_edit_modes_refuse_foreign_owner_mode_and_epoch(){let ids=vec![MutationId("energy:λ".into())];let foreign=ids.clone();let view=HistoryTransitionEditsView{mode:HistoryTransitionEditMode::Revert,mutation_ids:&ids};let mut cursor=HistoryTransitionWireCursor::default();let mut output=[37;1];assert_eq!(cursor.write_edits_view(&view,71,&mut output).unwrap(),1);output[0]=37;for foreign_view in [HistoryTransitionEditsView{mode:HistoryTransitionEditMode::Reinstate,mutation_ids:&ids},HistoryTransitionEditsView{mode:HistoryTransitionEditMode::Revert,mutation_ids:&foreign}]{assert!(cursor.write_edits_view(&foreign_view,71,&mut output).is_err());assert_eq!(output,[37]);}assert!(cursor.write_edits_view(&view,72,&mut output).is_err());assert_eq!(output,[37]);}
